"""Authored teaching content; PDF page numbers are 1-based, never slide labels."""
import re
COURSES = []

def course(key, slug, title, term, filename, chain, sections):
    rows = []
    for line in sections.strip().splitlines():
        fields = re.split(r'(?<!\\)\|', line)
        if len(fields) != 10:
            raise ValueError((key, len(fields), line[:80]))
        h, pages, body, formula, symbols, example, pitfall, flow, question, answer = fields
        rows.append(dict(h=h, pages=[int(x) for x in pages.split(',')], body=body,
                         formula=formula, symbols=symbols, example=example,
                         pitfall=pitfall, flow=flow.split('>'), question=question, answer=answer))
    assert len(rows) == 12, (key, len(rows))
    COURSES.append(dict(key=key,slug=slug,title=title,term=term,filename=filename,chain=chain,sections=rows))

